-- Heroes of Battle source-backed mechanical rules.
-- Mechanical summaries are concise; source pages remain authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('hob-3.5','heroes-of-battle-3-5','Heroes of Battle','HoB','Wizards of the Coast','dnd','3.5',
        'D&D 3.5 supplement for battlefield adventures, military characters, command, morale, and mass-conflict procedures.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,summary,tags,mechanics) AS (VALUES
('hob-siege-engines','Siege Engines','63-68','combat','subsystem',0,1,
 'Heroes of Battle expands and supersedes the Dungeon Master''s Guide siege-engine treatment for battlefield campaigns; siege weapons deal full damage to objects.',
 '["siege","combat","objects"]',
 '{"supersedes":"DMG pp.99-100 siege-engine treatment","designed_for_size":"Medium","full_damage_to_objects":true,"build":{"skill":"Craft (siege engine)","dc":20,"weekly_progress_gp":"check result x 20","laborers_assumed":3,"one_laborer_progress":"half","solo_progress":"quarter"},"setup_minutes":{"ballista":1,"other":10},"engines":[{"name":"light ballista","cost_gp":500,"range_increment_ft":100,"max_range_ft":1000,"crew":2,"hardness":5,"hp":25,"weight_lb":400,"size":"Medium","bolt":{"cost_gp":1,"damage":"3d8","critical":"19-20/x2","weight_lb":6}},{"name":"heavy ballista","cost_gp":1000,"range_increment_ft":120,"max_range_ft":1200,"crew":4,"hardness":5,"hp":675,"weight_lb":2000,"size":"Huge","bolt":{"cost_gp":1,"damage":"5d8","critical":"19-20/x2","weight_lb":6}},{"name":"battering ram","cost_gp":1000,"damage":"3d8","critical":"x2","crew":"4-10","hardness":5,"hp":600,"weight_lb":3000,"size":"Huge"},{"name":"heavy mangonel","cost_gp":800,"range_increment_ft":200,"min_range_ft":100,"max_range_ft":1000,"crew":4,"hardness":5,"hp":1350,"weight_lb":3000,"size":"Huge","shot":{"cost_gp":0.5,"damage":"3d6","weight_lb":50},"stone":{"cost_gp":2,"damage":"6d6","weight_lb":75}},{"name":"light mangonel","cost_gp":550,"range_increment_ft":150,"min_range_ft":75,"max_range_ft":750,"crew":2,"hardness":5,"hp":400,"weight_lb":2000,"size":"Large","shot":{"cost_gp":0.3,"damage":"2d6","weight_lb":30},"stone":{"cost_gp":1,"damage":"4d6","weight_lb":40}},{"name":"scorpion","cost_gp":1250,"range_increment_ft":200,"min_range_ft":100,"max_range_ft":1000,"crew":2,"hardness":5,"hp":400,"weight_lb":2000,"size":"Large","shot":{"cost_gp":0.5,"damage":"3d6","weight_lb":50},"stone":{"cost_gp":2,"damage":"6d6","weight_lb":75}},{"name":"siege tower","cost_gp":2000,"crew":9,"hardness":5,"hp":1800,"weight":"5 tons","size":"Gargantuan","inoperable_after_half_hp_damage":true},{"name":"heavy trebuchet","cost_gp":3000,"range_increment_ft":300,"min_range_ft":150,"max_range_ft":1500,"crew":8,"hardness":5,"hp":7500,"weight":"10 tons","size":"Colossal","shot":{"cost_gp":1,"damage":"7d6","weight_lb":100},"stone":{"cost_gp":4,"damage":"14d6","weight_lb":150}},{"name":"light trebuchet","cost_gp":1500,"range_increment_ft":250,"min_range_ft":125,"max_range_ft":1250,"crew":6,"hardness":5,"hp":3200,"weight":"4 tons","size":"Gargantuan","shot":{"cost_gp":0.7,"damage":"5d6","weight_lb":75},"stone":{"cost_gp":3,"damage":"10d6","weight_lb":100}}]}'),
('hob-operating-catapults','Operating Catapults','65-68','combat','procedure',0,1,
 'Non-ballista catapults aim at battlefield squares through crew actions, Profession checks, loading, and a special attack roll.',
 '["siege","catapult","profession"]',
 '{"aim":{"profession_dc":15,"aid_dc":10,"aid_bonus":2,"action":"one or more full-round crew actions"},"load":{"profession_dc":15,"strength_dc":10,"large_or_larger_time":"half","small_time":"double","tiny_can_load":false},"fire":{"action":"standard","roll":"1d20 + BAB + Intelligence modifier + range penalties + modifiers","target_square_ac":15},"vertical_clearance":"half range to target","no_line_of_sight_penalty":-6,"successive_visible_miss_bonus":{"step":2,"max":10},"successive_observed_miss_bonus":{"step":1,"max":5},"stone_save":{"type":"Reflex","dc":15,"success":"avoid"},"shot":{"damage":"half listed to target and adjacent squares","save_dc":15,"success":"half"},"after_success":"subsequent shots at same square automatically hit until re-aimed"}'),
('hob-aerial-bombardment','Aerial Bombardment','67-68','combat','procedure',0,1,
 'Airborne creatures can drop heavy objects as battlefield weapons using falling-object damage and special accuracy rules.',
 '["aerial","bombardment","falling-objects"]',
 '{"range_increment_ft":50,"above_250_ft":"always indirect","attack":{"target_square_ac":5,"improvised_penalty":-4,"maneuverability_penalty":{"average":-2,"poor":-4,"clumsy":-6}},"save":{"type":"Reflex","dc":15,"success":"avoid"},"dive_bombing":{"attack_bonus":2,"treated_as_charge":true,"ac_penalty":-2,"dive_distance_adds_to_fall_distance":true},"flight_load":{"light":"full speed","medium_or_heavy":"speed reduced by one-third"}}'),
('hob-arrow-volley','Volley of Arrows','68-70','combat','subsystem',0,1,
 'Ten or more contiguous projectile users can fire a coordinated area volley instead of selecting individual targets.',
 '["volley","ranged","battlefield"]',
 '{"minimum_archers":10,"contiguous":true,"action":"full-round","shots_per_archer":1,"commander_attack":"1d20 + BAB + Intelligence modifier + range penalties","target_ac":15,"target_shape":"same shape as archers formation","save":{"type":"Reflex","base_dc":15,"success":"avoid arrow damage"},"save_modifiers":{"arrow_enhancement":"lowest enhancement bonus","each_range_increment_after_first":-2,"half_archers_lack_line_of_sight":-2},"indirect":{"arc_height_ft_per_range_increment":10,"may_ignore_cover_between_archers_and_target":true,"total_cover_within_10_ft_of_archers_or_target_blocks":true},"direct":{"may_ignore_cover":false,"all_archers_need_clear_line":true}}'),
('hob-concentrated-volley','Concentrated Volley','69-70','combat','procedure',0,1,
 'Up to ten contiguous archers can focus full attacks on one 5-foot square for concentrated damage.',
 '["volley","ranged","concentrated"]',
 '{"maximum_archers":10,"target":"one 5-ft square","each_archer":"full attack","target_ac":20,"critical_possible":false,"damage":"one-fifth of arrows fired","save":{"type":"Reflex","base_dc":15,"success":"half"},"deflection":{"normal_volley":"ability to deflect at least one arrow negates normal volley damage","concentrated":"reduce effective arrows by twice arrows deflectable per round"}}'),
('hob-strategic-advantages','Strategic Advantages','70-72','battle','subsystem',0,1,
 'Large battles can award strategic advantages before or during battle; each advantage earned by PCs is worth 10 victory points.',
 '["strategy","victory-points","planning"]',
 '{"vp_per_advantage":10,"large_scale_only":true,"npc_actions_do_not_change_pc_vp":true,"bardic_knowledge":{"planning_dc":25,"during_battle_dc":30},"divination":{"qualifying":["commune","commune with nature","contact other plane"],"max_awards":1,"legend_lore_or_vision_can_substitute":true},"knowledge":{"dc":20,"categories":["arcana","architecture and engineering","dungeoneering","geography","history","local","nature","nobility and royalty","religion","the planes"]},"leadership":{"minimum_score":10,"pc_must_lead_at_battle_start":true},"scouting":{"must_complete_before_battle":true,"gather_information_dc":20},"terrain_fortification":{"personal_control_vp":10}}'),
('hob-battlefield-morale','Battlefield Morale','72-75','morale','subsystem',0,1,
 'Battlefield morale uses fear-based Will saves and a progression from heartened to crazed.',
 '["morale","fear","battle"]',
 '{"check":"Will save against fear","base_dc":20,"triggers":["creature at 50% or less full hp","unit at 50% casualties"],"modifiers":{"fatigued":-2,"exhausted":-5,"outnumbered_4_to_1":-5,"outnumbered_2_to_1":-2,"outnumbers_enemy_2_to_1":2,"outnumbers_enemy_4_to_1":5},"failure":"worsen one category","failure_by_10":"worsen two categories","natural_1_if_would_be_panicked":"crazed","conditions":{"heartened":"+1 morale on Will saves against fear/morale","normal":"no modifier","shaken":"shaken","frightened":"frightened","panicked":"panicked","crazed":"roll d100"},"crazed":{"01-20":"berserk","21-40":"cowering","41-60":"dazed","61-80":"deafened","81-100":"nauseated"}}'),
('hob-pc-morale','PC Morale Checks','75-76','morale','rule',1,0,
 'Optional variant extends battlefield morale checks to player characters if the group agrees to use it.',
 '["morale","pc","variant"]',
 '{"requires_group_agreement":true,"hp_trigger_fraction":0.5,"unit_casualty_trigger_fraction":0.5,"unit_includes":["PCs","cohorts","significant allies"],"unit_excludes":["followers","other low-level NPCs"]}'),
('hob-rally-check','Rally Checks','73-75','morale','procedure',0,1,
 'A rally check is a move action used to improve the morale of comrades who can see and hear the rallying character.',
 '["rally","morale","commander"]',
 '{"action":"move","roll":"1d20 + Charisma modifier + commander rating","language_dependent":true,"one_attempt_per_target_per_round":true,"dc":{"panicked":{"frightened":20,"shaken":25,"normal":30,"heartened":40},"frightened":{"shaken":20,"normal":25,"heartened":30},"shaken":{"normal":20,"heartened":25},"normal":{"heartened":20}},"modifiers":{"failed_rally_in_last_minute":-2,"rallier_at_half_hp_or_less":-2,"visible_enemy_fleeing":2,"diplomacy_or_intimidate_5_ranks":2,"no_enemy_visible":5},"magical_fear_rally_duration_rounds":1,"prebattle":{"time":"at least 1 minute","retry":false,"can_take_10":false}}'),
('hob-commander-rating','Commander Rating','75-78','command','subsystem',0,1,
 'Military rank is represented by commander rating 0 through 7 and contributes directly to rally checks.',
 '["command","rank","rally"]',
 '{"adds_to_rally":true,"ranks":[{"rating":0,"rank":"Private","troops":null},{"rating":1,"rank":"Corporal","troops":"1-4"},{"rating":2,"rank":"Sergeant","troops":"6-12"},{"rating":3,"rank":"Lieutenant","troops":"15-25"},{"rating":4,"rank":"Captain","troops":"30-100"},{"rating":5,"rank":"Major","troops":"100-500"},{"rating":6,"rank":"Colonel","troops":"500-5,000"},{"rating":7,"rank":"General","troops":"5,000+"}],"pulling_rank":{"skill":"Intimidate","bonus":"difference in commander ratings against lower-ranking target"}}'),
('hob-commander-auras','Commander Auras','75-78','command','subsystem',0,1,
 'A commander selects a qualifying aura at rating 1; normally one aura affects lower-rated allies within 30 feet and aura benefits never stack.',
 '["command","auras","morale"]',
 '{"first_rating":1,"normal_max_auras":1,"radius_ft":30,"minimum_ally_intelligence":3,"self_benefit":false,"no_benefit_to_ally_with_rating_gte_commander":true,"benefits_never_stack":true,"auras":[["Animal Commander","rating 1; neutral; wild empathy","animal/magical beast allies +2 morale saves; Int 1+"],["Archery Commander","rating 2; chaotic; Point Blank Shot","allies +1 morale ranged attacks; +1 volley save DC you direct"],["Bloodthirsty Commander","rating 3; evil","allies +1 morale damage against wounded creatures"],["Deathslayer Commander","rating 2; good; turn undead","living allies +1d6 morale melee damage vs undead"],["Defensive Commander","rating 2; lawful good","allies +1 morale AC"],["Doublestrike Commander","rating 5; chaotic good","ally natural 20 melee attack grants immediate extra melee attack"],["Dwarf Commander","rating 3; dwarf; lawful good","dwarf allies +2 morale AC, +4 vs giants"],["Elf Commander","rating 3; elf; chaotic good","elf allies +2 morale saves"],["Feral Commander","rating 3; neutral; Handle Animal 5","animal/magical beast allies +2 morale attacks; Int 1+"],["Giant-Killer Commander","rating 2; Small or smaller; good","+2 morale melee attacks vs foes at least two sizes larger"],["Goblinoid Commander","rating 3; goblinoid; lawful evil","goblinoid allies +2 morale melee attacks"],["Healing Commander","rating 3; good","healing an ally allows free rally check for that ally"],["Maneuvering Commander","rating 2; chaotic good","move at least 10 ft then +2 morale next melee attack that turn"],["Melee Commander","rating 3; lawful; BAB +2","allies +1 morale melee attacks"],["Mobile Commander","rating 3; chaotic","ally starting turn in aura gains +5 ft morale speed"],["Necromantic Commander","rating 2; evil; command/rebuke undead","Int 1+ undead allies +1d6 morale melee damage vs living"],["Opportunistic Commander","rating 1; chaotic","allies +1d6 morale damage on attacks of opportunity"],["Orc Commander","rating 3; orc; chaotic evil","orc allies +1d6 morale melee damage"],["Orderly Commander","rating 2; lawful","ally rallied by you gains +10 ft morale speed for 1 round"],["Protective Commander","rating 1; lawful","allies +1 morale saves"],["Pursuing Commander","rating 2; lawful evil","allies +1d6 morale damage vs frightened/panicked foes"],["Reckless Commander","rating 2; chaotic evil","ally starting in aura deals +1d6 morale damage on next charge"],["Runt-Squasher Commander","rating 2; Large+; evil","+2 morale attacks vs foes at least one size smaller"],["Sneaky Commander","rating 5; chaotic evil; sneak attack","allies +1d6 morale damage against flanked foes"],["Spellslinging Commander","rating 3; cast 1st-level spells; Spellcraft 5","damaging area spells cast by allies deal +1d6 morale damage"],["Steadfast Commander","rating 5; lawful good","allies +2 morale AC vs foes that moved at least 5 ft before attacking"],["Tyrannical Commander","rating 5; lawful evil; Intimidate 5","allies +5 morale on morale checks; failure makes them panicked"]]}'),
('hob-victory-points','Victory Points','78-85','battle','subsystem',0,1,
 'Victory points quantify how the PCs'' battlefield missions influence the outcome of a massive battle.',
 '["victory-points","missions","battle"]',
 '{"earned_collectively_by_pcs":true,"npc_actions_do_not_directly_earn_pc_vp":true,"awards":{"assist_friendly_troops":"1 VP per 10 allies, max 50; magical aid can justify more","attack_enemy_siege_engines":"10-60","defeat_enemy_units":"EL x 10","disrupt_enemy_command":"1 VP per 10 soldiers under command","disrupt_enemy_communications":"EL x 2, or 2-50 for large groups","disrupt_enemy_supply":"10-50","protect_defensive_point":"10-80","protect_intrinsic_point":"Table 4-10: 10-80; detailed heading: 10-100","protect_maneuver_point":"10-70","protect_offensive_point":"20-100","provide_intelligence":"10-30","seize_defensive_point":"20-100","seize_intrinsic_point":"10-90","seize_maneuver_point":"10-70","seize_offensive_point":"10-50"},"source_conflict":{"protect_intrinsic_point":{"detailed_heading":"10-100","table_4_10":"10-80"}}}'),
('hob-recognition-points','Recognition Points','85-92','rewards','subsystem',0,1,
 'Recognition points track individual military reputation and can be spent on decorations or promotions.',
 '["recognition","decorations","military"]',
 '{"earned_by_pcs_only":true,"awards":{"capture_enemy_standard":"half enemy unit EL","defeat_notable_unit":"enemy unit EL","fight_in_famous_battle":"3-5","fight_in_famous_campaign":"5-10","plant_standard":"3 when planted, then +EL for each later enemy-unit attack repulsed","rally_demoralized_unit":"EL of creatures rallied","receive_elite_training":"3-5","replace_fallen_leader":"commander rating x 2","rescue_endangered_unit":"2 x EL of surviving friendly unit","survive_overwhelming_odds":"5 x (EL of each significant combat - average PC level)"},"spending":["service decorations","decorations","promotion points"],"decorations_affect_npc_interactions":true}'),
('hob-promotions','Promotions','91-93','command','table',0,1,
 'Promotion points determine military rank and commander rating.',
 '["promotion","rank","recognition"]',
 '{"thresholds":[["0-9",0,"Private"],["10-24",1,"Corporal"],["25-74",2,"Sergeant"],["75-149",3,"Lieutenant"],["150-249",4,"Captain"],["250-399",5,"Major"],["400-599",6,"Colonel"],["600+",7,"General"]]}'),
('hob-battlefield-skills','Battlefield Skill Uses','93-96','skills','subsystem',0,1,
 'Heroes of Battle adds battlefield-specific uses for existing skills.',
 '["skills","battlefield","siege"]',
 '{"Bluff":{"use":"pep talk","opposed_by":"Sense Motive","success":"+2 next morale check, then -2 later morale checks same battle","action":"full-round","targets":"up to 10 creatures per Bluff rank","retry_hours":24,"veteran_sense_motive_bonus":6},"Craft (siege engine)":{"dc":20,"blacksmithing_or_weaponsmithing_substitution_penalty":-5},"Diplomacy":{"ranks":5,"rally_bonus":2},"Disable Device":{"normal_siege_engine_dc":20,"magic_siege_engine_dc":25,"hidden_sabotage_modifier":5,"time":"2d4 rounds"},"Disguise":{"use":"fake corpses","opposed_by":"Spot","real_corpses_3_to_1_bonus":2,"time":"1d3 minutes"},"Gather Information":{"dc":20,"time":"1d4+1 hours","effect":"strategic advantage in/near inhabited area"},"Handle Animal":{"teamwork_trick_dc":20},"Heal":{"makeshift_bandage":{"dc":12,"stabilizes_after_rounds":2,"failure_by_5":"target loses 1 hp"},"extended_aid":{"dc":20,"unconscious_wakes_after":"1 hour"}},"Intimidate":{"lower_rank_bonus":"commander rating difference","ranks":5,"rally_bonus":2},"Knowledge":{"strategic_advantage_dc":20,"planning_time":"1 hour","retry":false},"Profession (siege engineer)":{"use":"aim and operate indirect-fire catapults"},"Speak Language":{"use":"simple one-handed silent battle signals","fighter_class_skill_for_signals":true},"Spot":{"count_troops_dc":10,"maximum_group":1000,"under_or_equal_250_precision":"nearest 10","over_250_precision":"nearest 100","locate_commander_dc":20,"locate_artillery_dc":25,"artillery_range_precision_ft":30,"artillery_ignores_distance_modifier":true}}'),
('hob-teamwork-benefits','Teamwork Benefits','115-121','teamwork','subsystem',1,0,
 'A trained team of two to eight members can gain shared teamwork benefits when task-leader and team-member prerequisites are met.',
 '["teamwork","training","variant"]',
 '{"team_size":{"min":2,"max":8},"initial_training_weeks":2,"new_member_training_weeks":2,"maintenance":{"periods_per_year":4,"weeks_each":1},"normal_min_intelligence":3,"int_1_2_requires_teamwork_trick":true,"mindless_allowed":false,"task_leader_min_intelligence":8,"benefits_per_lowest_member_hd":"1 per 4 HD","swap_on_new_benefit":true,"communication_required":true,"benefits":[["Fearsome Roster","leader Intimidate 8; member Cha 13 or Intimidate 1","enemy morale penalty = 1 + one-quarter lowest team member HD when seeing 2+ team members"],["Friendly Fire Evasion","leader Spellcraft 4 + evasion; member base Reflex +2 + Spellcraft 1","evasion against team members spells"],["Friendly Fire Evasion, Improved","leader Spellcraft 6 + improved evasion; member prior teamwork benefit + base Reflex +3 + Spellcraft 1","improved evasion against team members spells"],["Heavy Cavalry","leader Handle Animal 4, Ride 8, Mounted Combat, Trample; member Ride 1","compressed mounted formation without squeeze penalties; forced overruns; mounts count one size larger for overruns"],["Infiltration","leader Hide 8 + Move Silently 8; member Hide 1 or Move Silently 1","move full speed without -5 Hide/Move Silently and remain mutually visible while contact maintained"],["Invisibility Sweep","leader Blind-Fight","standard action probes four adjacent squares; one member pinpointing invisible foe shares location with team until foe moves"],["Joint Grapple Escape","leader BAB +4 or Improved Grapple","aid another gives +4 or Strength modifier, whichever higher, to adjacent teammate escape check"],["Joint Bull Rush","leader Improved Bull Rush","single synchronized bull rush using strongest Strength bonus plus each additional member Strength bonus, minimum +1 each"],["Joint Ram","leader Improved Sunder","ram +2 damage per team member; comparable break checks gain +4 per aiding member"],["Long-Range Archery","leader Far Shot; member BAB +1","after a miss beyond one range increment, later team shots take half range penalty until target moves over 20 ft"],["Ranged Precision","leader BAB +4 + Precise Shot; member BAB +2","ranged-into-melee penalty -2 and team-member cover +2 AC"],["Scouting","leader Listen 8 + Spot 8; member Listen 1 + Spot 1 or Alertness","free team Spot and Listen check each round using lowest modifier +1 per extra member"],["Spellcaster Guardian","leader Combat Reflexes + Spellcraft 4; member Dex 13 or Spellcraft 1","adjacent teammate can intercept 1 + Dex bonus attacks of opportunity provoked by casting"],["Superior Flank","leader sneak attack +4d6; member BAB +3","two team flankers let all team melee attackers count as flanking; rogue levels combine against improved uncanny dodge"],["Team Rally","leader Cha 13 + commander rating 2; member commander rating 1","+1 rally per other visible/audible team member; teammate rallied by teammate improves two morale categories"]]}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'hob-rule-'||d.slug,'hob-3.5',d.source_page,d.slug,d.name,d.summary,d.summary,0,NULL,1,
       d.category,d.kind,d.is_variant,d.default_enabled,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL);
